import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.XwxSdVYF.js";const o="/VirtualC64/docs/assets/architecture.CwqOF0F9.svg",p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"title":"Architecture","kind":"page"},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),c={name:"guide/architecture.md"};function i(n,e,h,u,l,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture {#architecture}&quot;">​</a></h1><p>A typical app that uses the VirtualC64 core consists of two kinds of threads:</p><ul><li>The <strong>user threads</strong> are the threads of the front-end. They call the API functions. Any thread except the emulator thread is a user thread.</li><li>The <strong>emulator thread</strong> is created by <a href="/VirtualC64/docs/api/vc64-VirtualC64#launch">launch()</a>. It lives as long as the emulator object and computes frames and audio samples.</li></ul><p>The threads never touch each other&#39;s data directly. Requests that change the state of the emulator are handed over through a <em>command queue</em> and carried out by the emulator thread. The emulator reports events back through a <em>message queue</em>.</p><p><img src="'+o+'" alt=""></p><p>The diagram shows the three situations a front-end deals with:</p><ol><li><strong>Launch.</strong> Calling <a href="/VirtualC64/docs/api/vc64-VirtualC64#launch">launch()</a> creates the emulator thread and registers the message callback. The callback is the only code of the front-end that runs on the emulator thread. It must not call back into the API, but forward the message to a user thread.</li><li><strong>Asynchronous call.</strong> Functions with an <code>Async</code> suffix, such as <a href="/VirtualC64/docs/api/vc64-VirtualC64#runasync">runAsync()</a>, put a command into the queue and return at once. The emulator thread picks it up at the start of its next update cycle, so a state change never happens in the middle of a frame. The outcome arrives later as a message.</li><li><strong>Blocking call.</strong> Functions without a suffix, such as <a href="/VirtualC64/docs/api/vc64-VirtualC64#poweroff">powerOff()</a>, queue the same command, but wait until it has been carried out. They return the outcome directly, or throw an exception. Functions that send a message will do so for blocking calls, too.</li></ol><p>Reading the state of the emulator does not involve the queue. Getters such as <a href="/VirtualC64/docs/api/vc64-VirtualC64#isrunning">isRunning()</a> read the data directly, on the calling thread.</p>',8)])])}const f=t(c,[["render",i]]);export{p as __pageData,f as default};
